def get_lr(it, warmup_iters, lr_decay_iters, learning_rate, min_lr):
    """Cosine learning rate schedule with linear warmup."""
    if it < warmup_iters:
        return learning_rate * (it + 1) / (warmup_iters + 1)
    if it > lr_decay_iters:
        return min_lr
    decay_ratio = (it - warmup_iters) / (lr_decay_iters - warmup_iters)
    assert 0 <= decay_ratio <= 1
    coeff = 0.5 * (1.0 + math.cos(math.pi * decay_ratio))
    return min_lr + coeff * (learning_rate - min_lr)

def configure_optimizers(self, weight_decay, learning_rate, betas, device_type):
    param_dict = {pn: p for pn, p in self.named_parameters() if p.requires_grad}
    muon_p = [p for n, p in param_dict.items() if p.dim() >= 2 and 'wte' not in n and 'wpe' not in n and 'lm_head' not in n]
    adam_decay = [p for n, p in param_dict.items() if p.dim() >= 2 and ('wte' in n or 'wpe' in n or 'lm_head' in n)]
    adam_nodecay = [p for n, p in param_dict.items() if p.dim() < 2]
    class Muon(torch.optim.Optimizer):
        def __init__(self, params, lr=0.02, momentum=0.95, ns_steps=5, wd=0.0):
            super().__init__(params, dict(lr=lr, momentum=momentum, ns_steps=ns_steps, wd=wd))
        @staticmethod
        def _ns(G, steps=5):
            X = G.bfloat16() / (G.norm() + 1e-7)
            if G.size(0) > G.size(1): X = X.T
            a, b, c = 3.4445, -4.7750, 2.0315
            for _ in range(steps):
                A = X @ X.T; X = a*X + b*(A@X) + c*(A@(A@X))
            if G.size(0) > G.size(1): X = X.T
            return X
        @torch.no_grad()
        def step(self):
            for g in self.param_groups:
                for p in g['params']:
                    if p.grad is None: continue
                    if g['wd'] > 0: p.mul_(1 - g['lr'] * g['wd'])
                    s = self.state.setdefault(p, {'b': torch.zeros_like(p.grad)})['b']
                    s.lerp_(p.grad, 1 - g['momentum'])
                    n = p.grad.lerp(s, g['momentum'])
                    if n.dim() == 2:
                        orig = n.shape
                        if orig[0] == 3 * orig[1]:
                            parts = n.split(orig[1])
                            U = torch.cat([self._ns(part, g['ns_steps']) for part in parts])
                            scale = max(1, orig[0] // orig[1]) ** 0.5
                        else:
                            U = self._ns(n, g['ns_steps'])
                            scale = max(1, orig[0] / orig[1]) ** 0.5
                        p.data.add_(U.to(p.dtype), alpha=-g['lr'] * scale)
                    else:
                        p.data.add_(n, alpha=-g['lr'])
    fused = 'fused' in inspect.signature(torch.optim.AdamW).parameters
    muon_opt = Muon([{'params': muon_p, 'lr_scale': 0.02 / learning_rate}], lr=0.02, wd=weight_decay)
    adam_opt = torch.optim.AdamW(
        [{'params': adam_decay, 'weight_decay': weight_decay},
         {'params': adam_nodecay, 'weight_decay': 0.0}],
        lr=learning_rate, betas=betas, fused=fused)
    class CombinedOpt:
        def __init__(self, opts):
            self.optimizers = opts
            self.param_groups = sum([o.param_groups for o in opts], [])
        def zero_grad(self, set_to_none=True):
            for o in self.optimizers: o.zero_grad(set_to_none=set_to_none)
        def step(self):
            for o in self.optimizers: o.step()
    print(f"using Muon (lr=0.02, wd={weight_decay}) + AdamW")
    return CombinedOpt([muon_opt, adam_opt])

